// P2 Theme I · Forming nation-states — from Theme_I_Forming_Nation_States_Study_Notes
// (plus Theme_I_Every_Case_Study_and_Statistic_Compilation for the same facts).
(function(){
const S = "Forming Nation-States study notes", S2 = "Theme I case study & statistic compilation";
const add = (sec, o) => CASES.push(Object.assign({ t:"ns", sec, src:S, qs:"me" }, o));

/* ── Framework ── */
add("Framework", { id:"ns-forms", title:"Four forms of government in independent SEA", when:"1945–2000",
  q:"What were the democratic and authoritarian features of Southeast Asian governments? Name the four forms of government and give examples.", exp:"The four forms are not fixed categories: several states moved between them over time, so the same country can appear twice (Thailand as a constitutional monarchy from 1932 and a military government 1947–73; the Philippines as an early democracy, then under martial law). Malaysia shows forms can overlap, being both a parliamentary democracy and a constitutional monarchy. Use this to show change over time, since only Malaysia and Singapore kept parliamentary democracy throughout.", qs:"notes",
  pts:["Parliamentary democracies: early Philippines, Indonesia, Burma; Malaysia and Singapore throughout",
       "Constitutional monarchies: Cambodia, Laos, Malaysia, Thailand from 1932",
       "Military governments: Thailand 1947–73, Burma from 1962, Indonesia's New Order, Philippines under martial law",
       "Communist states: Vietnam, Cambodia, Laos"] });
add("Framework", { id:"ns-factors", title:"Three factors for the establishment of governments", when:"framework",
  q:"Why were different forms of government established over time in Southeast Asia? State the three factors.", exp:"These three factors explain why governments differed: how power was handed over set the starting conditions, the choices and skills of elites and the pressure from the masses decided whether democracy held, and Cold War intervention determined which groups could seize and keep power. Studying them before, at and after independence lets you show how one factor gave way to another in importance, which is the basis of a good evaluative essay.", qs:"notes",
  pts:["Decolonisation experience: colonial attitudes, degree of tutelage, peaceful or violent transfer",
       "Role of local political elites and masses: beliefs and styles of elites, how they distributed power, familiarity with constitutional processes, masses' desire for influence",
       "Cold War developments: superpower intervention (esp. US, Domino Theory) and communist support networks",
       "Studied chronologically: before, at and after independence"] });
add("Framework", { id:"ns-consol", title:"Consolidation of power: definition and four factors", when:"framework",
  q:"Define power and consolidation of power, and state the four factors used to analyse consolidation.", exp:"Consolidation is about whether a government could make its power stick, so the test is durability: a regime that lasted consolidated successfully, one that was replaced failed. Because the monarchy, military, religious bodies and voters also held power, governments had to either win them over (legitimacy) or contain them (controlling opposition). The four factors give a consistent structure to compare any case study, for example why Suharto fell but the VCP endured.",
  pts:["Power: ability to achieve a desired outcome through force, incentives or influence; monarchy, military, religious institutions, political groups and electorate also hold power",
       "Consolidation: strengthening capacity to exercise power, chiefly by building legitimacy and controlling opposition",
       "Success measured by regime stability/durability; failure leads to new governments",
       "Four factors: role of government leaders; sources of power and legitimacy; political challenges and popular opposition; Cold War developments"] });
add("Framework", { id:"ns-clusters", title:"Country clusters", when:"framework",
  q:"Classify the SEA states into the three decolonisation clusters and three consolidation clusters.", exp:"The clusters group countries by shared causes so you can compare rather than narrate. In decolonisation, the key variables were colonial willingness to cede power and preparation: tutelage produced a professional, apolitical military, while violent struggle legitimised communists and soldiers. In consolidation, the clusters sort outcomes: Cluster A swung back to democracy, Cluster B stayed authoritarian, and Cluster C kept semi-democracy. Note that peaceful transfer did not guarantee democracy, since Burma ended up under the military.",
  pts:["Peaceful with tutelage: Philippines, Malaya, Singapore (communists suppressed with colonial support; military professional and apolitical)",
       "Peaceful without tutelage: Burma, Cambodia, Laos (little constitutional preparation)",
       "Violent re-imposition: Vietnam, Indonesia (communism/military legitimised by revolutionary struggle)",
       "Unstable, shifted back to democracy: Indonesia 1998, Philippines 1986, Thailand 1973–76 and 1992",
       "Stable authoritarian: Burma (Tatmadaw 1962–2010), Vietnam (VCP since 1976); semi-democracies: Singapore, Malaysia"] });

/* ── Decolonisation ── */
add("Decolonisation", { id:"ns-japocc", title:"Impact of the Japanese Occupation and colonial attitudes", when:"1942–1945",
  q:"How did the Japanese Occupation and differing colonial attitudes shape decolonisation?", exp:"The Occupation broke the myth of colonial invincibility and gave nationalists political and military experience, so returning powers faced stronger movements. What then decided the path was colonial attitude: where the US and Britain were willing to cede control they worked with elites towards democracy, while French and Dutch attempts to re-impose control produced violent revolutions that empowered communists and the military. This links decolonisation directly to the forms of government that followed.",
  pts:["Occupation discredited colonial powers and politicised/militarised nationalists",
       "Powers willing to release colonies worked with local elites for peaceful transfer to democracy",
       "Powers wanting re-imposition clashed violently with revolutionary, often communist-influenced, movements",
       "US and Britain more willing than France and the Netherlands to cede control, provided democracy resulted",
       "Thailand excluded as a case study: never colonised"] });
add("Decolonisation", { id:"philindep", title:"Philippines: colonial structures and the Bell Act", when:"1907–1946",
  q:"What colonial structures prepared the Philippines for independence, and why was the Bell Act controversial?", exp:"Long US tutelage (an elected Assembly from 1907, a fixed timetable and a constitution) meant the Philippines had familiar democratic institutions at independence, which is why it fits the peaceful-with-tutelage cluster. The Bell Act shows the limits of that independence: by tying rehabilitation aid to free trade and parity rights, the US kept economic leverage, which critics saw as surrendering sovereignty. Useful for arguing that formal independence came with continued dependence on the US.",
  pts:["1907 Philippine Assembly and elected Senate/House",
       "1934 Tydings–McDuffie Act: independence after a 10-year transition; 1935 Constitution; elections April 1946; independence 4 Jul 1946",
       "1946 Bell Act tied US$500m+ rehabilitation aid to free trade and a 'parity clause' giving US citizens equal rights to exploit resources",
       "Critics saw it as violating the constitution and surrendering sovereignty"],
  clue:"A 1946 act that tied US$500m of rehabilitation aid to a parity clause on natural resources." });
add("Decolonisation", { id:"ns-philelites", title:"Philippines: elites, communists and the military at independence", when:"1930–1954",
  q:"Describe the Philippine elites, communist movement and military at independence.", exp:"The pattern is that the US-aligned elite won out: the ilustrado elite profited from Bell Act free trade and dominated over radicals, while the communist Huks were defeated through land reform. The AFP, built under American command and tied to the US by the 1947 bases agreement, stayed professional and aligned with Washington. Together this explains why the Philippines began independence as a pro-US democracy dominated by landed elites.",
  pts:["Pro-US ilustrado elite (Manuel Roxas, Liberal Party) benefited from Bell Act free trade (sugar) and dominated over the Nationalist Party/Democratic Alliance",
       "PKP (1930) militarised as the Hukbalahap under Luis Taruc in WWII, targeting landlords and Japanese",
       "Huk insurgency 1946–54, defeated after Magsaysay's land reforms",
       "AFP founded 1935 under MacArthur; part of US forces in WWII; 1947 Military Bases Agreement aligned it to the US (Korea, Second Indochina War)"] });
add("Decolonisation", { id:"ns-malayastruct", title:"Malaya: colonial structures to independence", when:"1946–1957",
  q:"Trace Malaya's colonial structures from the Malayan Union to independence.", exp:"Malaya’s structures were shaped by bargaining: the centralised Malayan Union provoked Malay resistance, so Britain switched to a Federation that protected Malay special position, laying the ethnic basis of later politics. The Emergency then pushed Britain to speed up self-government to undercut the communists, which is why the timetable shrank from 25 to 8 years. Because the military stayed under British command, it never became a political actor, unlike in Burma or Indonesia.",
  pts:["Pre-war indirect rule via the Residency system",
       "1946 Malayan Union (centralised, jus soli) provoked Malay backlash → Federation safeguarding Malay special position",
       "Emergency shortened the independence timetable from 25 to 8 years",
       "1951 Member System; 1956 Reid Commission; independence 31 Aug 1957",
       "Military stayed under British command until 1957 and did not shape the path to independence"] });
add("Decolonisation", { id:"ns-alliance", title:"Malaya: rise of the Alliance", when:"1946–1957",
  q:"How did the UMNO–MCA–MIC Alliance emerge and win independence?", exp:"The Alliance grew out of British and Malay preferences: UMNO arose to defend Malay interests against the Malayan Union, and Britain promoted the MCA as a moderate Chinese alternative to the communists. Their cooperation, joined by the MIC, showed the British that a multi-ethnic, anti-communist partner existed, and the 51/52 landslide plus the Tunku’s firmness at Baling earned their trust. This explains why power was transferred peacefully to a stable coalition.",
  pts:["UMNO formed in response to the Malayan Union",
       "MCA groomed by the British as an anti-communist alternative to the MCP",
       "UMNO–MCA cooperation from the 1952 municipal elections; MIC joined Oct 1954",
       "Alliance won 51/52 seats in 1955",
       "Tunku's diplomacy and firmness at the 1955 Baling Talks won British trust"],
  clue:"A communal coalition that began in 1952 municipal polls and won 51 of 52 seats in 1955." });
add("Decolonisation", { id:"malayaemergency", title:"The Malayan Emergency", when:"1948–1960",
  q:"How did the British defeat the MCP during the Emergency?", exp:"Britain beat the MCP by combining force with politics: resettlement in New Villages cut guerrillas off from rural Chinese support, while hearts-and-minds and faster political reform removed their main argument that only revolution would bring independence. Once Malaya was clearly moving to independence under the Alliance, the MCP lost its rationale as well as the armed struggle. This is why Malaysia never faced a strong post-independence communist insurgency.",
  pts:["MCP outlawed 1948 after the MNLA killed three European planters; strong rural Chinese support and jungle veterans",
       "Templer: New Villages resettlement (Briggs Plan) + hearts and minds + accelerated political reform; SAS jungle sweeps",
       "By 1954 five states declared 'white areas'",
       "Baling Talks (1955) failed; MCP lost both armed struggle and political rationale by 1957",
       "Second Emergency 1968–89 also failed; Hat Yai Accords 1989"],
  clue:"A 1948–60 insurgency fought with New Villages, the Briggs Plan and 'white areas'." });
add("Decolonisation", { id:"ns-sgstruct", title:"Singapore: colonial structures", when:"1946–1965",
  q:"How did Singapore's colonial structures develop up to Merger and Separation?", exp:"Singapore was kept apart from Malaya because Britain valued it as a strategic colony and entrepot, so its constitutional development ran separately through gradual elected councils and the Rendel Commission. This steady widening of the electorate produced Westminster-style institutions and the PAP’s 1959 win. Because defence remained a British responsibility, Singapore had no military that could act politically, and only built its own after Separation in 1965.",
  pts:["Excluded from Malayan Union/Federation as a strategic Crown Colony and entrepot",
       "Legislative Council elections 1948, 1951; 1953 Rendel Commission expanded Assembly and electorate",
       "SLF won 1955; PAP won 1959 (43/51): Westminster-style structures",
       "Joined Malaysia 16 Sep 1963; separated 9 Aug 1965",
       "Defence a British responsibility; own armed forces only after 1965"] });
add("Decolonisation", { id:"ns-sgelites", title:"Singapore: SLF and PAP", when:"1954–1959",
  q:"Who founded the SLF and PAP, and how did the PAP win in 1959?", exp:"This card shows how Singapore’s self-government was won in stages by local elites. Marshall’s failure in London and Lim Yew Hock’s crackdown on left-wing unions reassured Britain that local leaders would contain the left, earning full internal self-government. The PAP’s 1959 landslide relied partly on its pro-communist wing’s union base, which explains the later internal struggle once the party was in power.",
  pts:["SLF (Lim Yew Hock, Francis Thomas, David Marshall) founded April 1954",
       "PAP (Lee Kuan Yew, Toh Chin Chye, Lim Chin Siong) founded Nov 1954",
       "Marshall resigned as Chief Minister after failed 1956 London talks",
       "Lim Yew Hock cracked down on left-wing unions, winning full internal self-government",
       "PAP won 43/51 in 1959, partly via its pro-communist faction's union control"] });
add("Decolonisation", { id:"spore59", title:"PAP split, Merger and Operation Cold Store", when:"1959–1963",
  q:"How did Lee Kuan Yew deal with the pro-communists in the PAP?", exp:"Lee’s moderates and the pro-communists had worked together to win power but split over merger, because merger with anti-communist Malaya would curb the left. After narrowly surviving the confidence vote, Lee used merger as a way to contain the pro-communists, won the referendum, and Operation Cold Store then removed the left-wing opposition. This fits the pattern of communists being suppressed with colonial support in the peaceful-with-tutelage cluster.",
  pts:["Split 1959–61 between Lee's moderates and Lim Chin Siong's pro-communists over merger",
       "Failed 1961 Anson by-election manoeuvre; confidence vote 27–8 with 16 abstentions; 13 assemblymen expelled",
       "Barisan Sosialis formed Aug 1961",
       "Lee sought merger to contain pro-communists; Merger Referendum won Sep 1962",
       "Operation Cold Store (1963) removed 100+ left-wing activists"],
  clue:"A 27–8 confidence vote with 16 abstentions, followed by a new opposition party in August 1961." });
add("Decolonisation", { id:"ns-burmalegacy", title:"Burma: colonial legacy and the AFPFL", when:"1885–1946",
  q:"What colonial legacy and pressures shaped Burma's road to independence?", exp:"Harsh colonial rule and Indian immigration built strong nationalist resentment, and Burma already had some experience of an elected legislature, though under a British veto. Aung San’s AFPFL aligned with the returning British, which gave it a claim to lead, but when Britain proposed three more years of direct rule, mass pressure from rallies and armed veterans forced London to commit to independence. The role of armed veterans foreshadows the military’s later political weight.",
  pts:["Third Anglo-Burmese War (1885); harsh rule and Indian immigration fuelled nationalism (Footwear Controversy 1917; Saya San Rebellion 1930–32)",
       "Pre-war elected bicameral legislature with a Burmese PM, subject to British veto",
       "Aung San's AFPFL fought the Japanese and aligned with returning British",
       "1945 White Paper proposed 3 years of direct rule; mass rallies and People's Volunteer Organisations forced commitment to independence"] });
add("Decolonisation", { id:"burmaindep", title:"Burma: Aung San–Attlee, Panglong and the 1947 election", when:"1947–4 Jan 1948",
  q:"How was Burmese independence negotiated and what happened to Aung San?", exp:"Independence was negotiated quickly, and the Panglong Agreement depended heavily on Aung San’s personal standing with minorities, with the Karens largely outside it. His assassination therefore removed the one leader who could hold the Burman majority and minorities together; U Nu lacked that trust. This helps explain why ethnic insurgency and AFPFL disunity weakened Burmese democracy soon after 1948.",
  pts:["Jan 1947 Aung San–Attlee Agreement: independence within a year; minorities could opt in",
       "Feb 1947 Panglong Agreement: minority rights (Shan, Kachin, Chin); Karens largely boycotted",
       "April 1947: AFPFL won 173/210 Constituent Assembly seats",
       "Aung San assassinated 19 Jul 1947 aged 32 by gunmen linked to U Saw; succeeded by U Nu, who lacked his standing with minorities",
       "Independence 4 Jan 1948"],
  clue:"A 1947 landslide of 173 of 210 seats, followed by its leader's assassination at 32." });
add("Decolonisation", { id:"ns-burmaconst", title:"Burma: 1947 Constitution, communists and military", when:"1946–1948",
  q:"Why were Burma's elites unprepared for democracy, and what were the roles of communists and the military?", exp:"Burma had a democratic constitution on paper, but the swift British withdrawal left no time to build a lasting power-sharing design or elite experience of democratic compromise, which is what places it in the without-tutelage cluster. Expelling the communists made the AFPFL acceptable to Britain (Pluvier) but pushed them into insurgency. Meanwhile the BIA/BNA and Aung San’s re-arming showed the army could act as an independent power source, setting up later military rule.",
  pts:["1947 Constitution: Chamber of Nationalities + Chamber of Deputies, rotating ceremonial President, PM heads government",
       "No long-term power-sharing design; swift (<3 years) British withdrawal left elites unprepared",
       "Red Flag (Thakin Soe) expelled from AFPFL Jan 1946; White Flag (Than Tun) Oct 1946; Pluvier: made AFPFL 'acceptable in British eyes'",
       "Thirty Comrades → BIA/BNA (30,000) helped retake Rangoon May 1945; PVO re-arming showed military as independent power source"] });
add("Decolonisation", { id:"ns-cambodia", title:"Cambodia: road to independence", when:"1863–9 Nov 1953",
  q:"How did Cambodia gain independence from France?", exp:"France offered only partial independence, keeping key powers, which gave Sihanouk a cause to champion. Although the Democratic Party won elections and the 1947 constitution made him a constitutional monarch, Sihanouk overrode parliamentary politics by ruling directly and then led the ‘royal crusade’, using France’s weakening position in Indochina to win full independence. This shows the transfer was peaceful but did little to root democratic practice, strengthening the monarchy instead.",
  pts:["French protectorate from 1863 at King Norodom's request; monarchy preserved; Japan prompted nominal independence Mar 1945",
       "1948 treaty: 'fifty percent independence' — France kept foreign policy, judiciary, finance, customs, bases",
       "Democratic Party (Sisowath Yuthevong) won 1946 (50/67), 1947 and 1951; Liberal Party (Norindeth) rural elites; 1947 constitution made Sihanouk constitutional monarch",
       "June 1952 Sihanouk dismissed cabinet, ruled directly (to Feb 1955)",
       "1953 'royal crusade': exile to Siem Reap with Lon Nol; independence 9 Nov 1953"],
  clue:"A king who called a 1948 treaty 'fifty percent independence' and led a 'royal crusade' in 1953." });
add("Decolonisation", { id:"ns-laos", title:"Laos: road to independence", when:"1893–1954",
  q:"How did Laos become independent and what rival government emerged?", exp:"Laos had weak pre-war nationalism and was a fragmented former kingdom, so independence came mainly through France’s wider defeat in Indochina rather than local struggle. It became a constitutional monarchy with little constitutional preparation, fitting the without-tutelage cluster. Crucially, Souphanouvong’s Vietminh-backed Pathet Lao set up a rival government from the start, a division that later Cold War intervention turned into civil war and communist victory.",
  pts:["Lan Xang split into Luang Prabang, Vientiane, Champassak (18th c.); French protectorate over Luang Prabang 1893",
       "Minimal pre-war nationalism; Japan granted self-government; France returned post-war",
       "Oct 1953 independence within French Union; full independence after 1954 Geneva",
       "Royal Lao Government: King Sisavang Vong, PM Souvanna Phouma",
       "Prince Souphanouvong's Pathet Lao set up a rival northeast government with Vietminh aid"] });
add("Decolonisation", { id:"ns-vietdecol", title:"Vietnam: French rule and the DRV", when:"1930–Mar 1946",
  q:"Why did Vietnamese nationalism become revolutionary, and what did the 1946 Ho–Sainteny Agreement provide?", exp:"Because France was the most repressive power and the Brazzaville Declaration ruled out autonomy, there was no peaceful route to independence, so nationalism became revolutionary. The Vietminh gained broad support by stressing independence over social revolution and building rural control, letting it declare the DRV in 1945. The Ho–Sainteny Agreement fell short of full independence and kept Cochin China French, which set up the conflict that followed.",
  pts:["France the most repressive colonial power; 1944 Brazzaville Declaration ruled out autonomy outside the Empire",
       "ICP (1930), Vietminh (1941) stressed independence over social revolution; Giap controlled much of Tonkin by 1945",
       "Aug 1945 DRV declared; 10 of 15 cabinet members ICP",
       "Mar 1946 Treaty of Hanoi: DRV a 'free state' in an Indochinese Federation, France kept Cochin China"] });
add("Decolonisation", { id:"vietnamindep", title:"First Indochina War and Ho's strategy", when:"Nov 1946–1954",
  q:"How did the Vietminh win, and why did it gain broad support despite being communist-led?", exp:"The Haiphong bombardment turned negotiation into war, and the Vietminh won by building rural legitimacy through parallel administrations and land redistribution, then defeating France at Dien Bien Phu. Ho’s moderation let a communist-led movement win wide nationalist support. Because the army was inseparable from the Party, Vietnam’s military never became an independent political force, unlike in Burma or Indonesia. The cancelled Geneva elections show how US fears under the Domino Theory shaped the outcome.",
  pts:["Haiphong bombardment 23 Nov 1946: 2,000–6,000 civilian deaths, triggered war",
       "Guerrilla warfare with parallel administrations; 630,000 ha redistributed to peasants",
       "Dien Bien Phu 7 May 1954 (artillery hauled up slopes); Geneva 17th parallel; elections never held (Diem, US feared Vietminh win)",
       "Ho's moderation: no wide social revolution, co-opted middle class, promised minority rights, dissolved ICP Nov 1945",
       "Military inseparable from Party: 'the party commands the gun' (Mao)"],
  clue:"A movement that redistributed 630,000 hectares and dissolved its own communist party in November 1945 to broaden support." });
add("Decolonisation", { id:"ns-indoprewar", title:"Indonesia: pre-war nationalism and Japanese occupation", when:"1914–1945",
  q:"How did Dutch rule and Japanese occupation shape Indonesian nationalism?", exp:"Dutch rule allowed only a powerless Volksraad and crushed both the PNI and the PKI, so nationalism was radicalised rather than channelled into constitutional politics. The Japanese reversed this by freeing Sukarno, giving him administrative experience and arming Indonesians through PETA. That is why the Republic had a ready leader and army in 1945, and why the military later gained so much legitimacy and political influence.",
  pts:["Ethical Policy allowed only a powerless Volksraad (1918)",
       "ISDV (1914, PKI forerunner); PNI (1927, Sukarno) suppressed by 1931; PKI revolt crushed 1926 (Boven Digul)",
       "Japan released Sukarno, gave administrative experience (Central Advisory Council)",
       "PETA (1943, 65,000): first time Indonesians armed in large numbers; backbone of Republican Army"] });
add("Decolonisation", { id:"indonesiarev", title:"Indonesian Revolution", when:"17 Aug 1945 – 2 Nov 1949",
  q:"Trace the Indonesian Revolution from the declaration to the Hague Agreement.", exp:"The Dutch tried to re-impose control, so independence had to be won through armed struggle, with Surabaya becoming a symbol of resistance. The failed agreements and Police Actions show Dutch unwillingness to cede power, but they also turned international opinion, especially the US threat to Marshall Aid, against the Netherlands. This shows how violent decolonisation legitimised the army and how Cold War concerns shaped the final settlement.",
  pts:["17 Aug 1945 Sukarno declared independence under pemuda pressure; Dutch returned (with British) planning a federal USI",
       "Battle of Surabaya (Oct–Nov 1945): up to 15,000 Indonesian and 600 Allied deaths incl. Brigadier Mallaby",
       "Linggadjati (Nov 1946) broke down; First Police Action (Aug 1947) → Yogyakarta capital, UN condemnation; Renville (Jan 1948) broke down",
       "Second Police Action (Dec 1948): US threatened Marshall Aid (Jan 1949)",
       "Hague Roundtable Aug–Nov 1949; independence 2 Nov 1949, Sukarno president"],
  clue:"A revolution with two Dutch 'Police Actions' and a battle that killed a British brigadier." });
add("Decolonisation", { id:"ns-madiun", title:"Madiun Affair", when:"Sep 1948",
  q:"What was the Madiun Affair and why did it matter?", exp:"When the PKI declared a Soviet Republic at Madiun, Sukarno had the Republican Army crush it, and this proved the Republic was anti-communist. That reassured the US, which helps explain the strong American pressure on the Dutch after the Second Police Action. The episode also boosted the army’s standing as defender of the Republic, laying the ground for its later political role under Suharto.",
  pts:["PKI (founded 1924) had rural mass support",
       "Sep 1948 PKI/PSI declared an Indonesian Soviet Republic at Madiun",
       "Sukarno ordered the Republican Army to suppress it: c.8,000 dead, 35,000 arrested",
       "Won US trust in Sukarno as anti-communist",
       "Army (from PETA) gained legitimacy, setting stage for Suharto"],
  clue:"A 1948 declaration of a Soviet Republic, crushed by the Republican Army with about 8,000 dead." });

/* ── Early democracies ── */
add("Early democracies", { id:"ns-failure", title:"Why early democracies failed", when:"1947–1972",
  q:"State the four factors behind the failure of early democracies and the dates each country turned authoritarian.", exp:"These factors explain why most early democracies collapsed by 1972: elites prone to authoritarianism, coalitions held together only by anti-colonialism that split once in power, and little experience of democratic compromise all made a strongman seem necessary. The masses’ demands created unrest that the military suppressed, which raised its own influence. The notes judge the critical variable to be elites’ ability to compromise and to accommodate the masses, not the form of government itself.", qs:"notes",
  pts:["Only Malaysia and Singapore sustained democracy; Thailand 1947, Indonesia 1959, Burma 1962, Philippines 1972",
       "Political beliefs of elites (Marcos, Sukarno, Phibun prone to authoritarianism)",
       "Distribution of power: groups united only by anti-colonialism clashed; military seemed better alternative",
       "Unfamiliarity with constitutional processes; 'strongman' seemed needed",
       "Masses' desire for influence; military's suppression of unrest raised its influence"] });
add("Early democracies", { id:"ns-patron", title:"Philippines: patron-client politics", when:"1946–1965",
  q:"How did patron-client networks undermine Philippine democracy?", exp:"Because parties were near-identical vehicles for patronage rather than ideology, politicians switched freely and governed to reward allies, as with Roxas, Quirino’s ‘ten percenters’, Garcia and Macapagal. A small oligarchy of families captured the state, so democratic institutions served private interests and long-term development stayed weak. This illustrates the distribution-of-power factor and explains public disillusion that Marcos later exploited.",
  pts:["Parties (Liberal, Nationalist) near-identical; party-switching common (Marcos switched to run in 1965)",
       "'Old oligarchy' of c.200 families",
       "Roxas gave allies US funds; Quirino's 'ten percenters' demanded bribes",
       "Garcia relied on warlords; Macapagal overspent despite frugality pledge (Ricklefs)",
       "Self-interested, sometimes kleptomaniacal leadership; weak development"] });
add("Early democracies", { id:"ns-philconst", title:"Philippines: constitution and the masses", when:"1935–1957",
  q:"Why did the 1935 Constitution's checks fail, and what did Magsaysay achieve?", exp:"The 1935 Constitution’s US-style checks existed, but patron-client politics hollowed them out: elections were rigged and an oligarch-dominated Congress blocked reform. Magsaysay shows the alternative, as popular support and land reform alongside force defeated the Huks, yet his death returned the old elite to dominance. This shows how unmet popular demands persisted and fed later instability under Marcos.",
  pts:["US-style checks (President, bicameral Congress, Supreme Court) undermined by patronage",
       "Election rigging common; Magsaysay used the military to protect ballot boxes (1953)",
       "Oligarch-dominated Congress caused gridlock, blocking Magsaysay's land reform",
       "Urban middle class and peasantry elected Magsaysay 1953; force + land reform beat the Huks by 1954",
       "Died in 1957 air crash; ilustrado dominance returned"] });
add("Early democracies", { id:"ns-martiallaw", title:"Marcos declares martial law", when:"1965–21 Sep 1972",
  q:"Why did Marcos declare martial law in 1972?", exp:"Marcos already saw democracy as ‘wasteful and paralyzing’, and mounting inequality, the communist CPP/NPA, the MNLF and student unrest such as the First Quarter Storm gave him a justification. He used the Plaza Miranda bombing and the Muslim insurgency to declare martial law, presenting it as the route to a ‘New Society’. This combines the elite-beliefs and mass-unrest factors and marks the Philippines’ shift to authoritarianism.",
  pts:["Viewed democracy as 'wasteful and paralyzing'; re-elected 1969",
       "Faced inequity, the CPP (1968) and NPA, and the MNLF in Mindanao",
       "First Quarter Storm Jan 1970: four students killed",
       "Cited Plaza Miranda bombing (Aug 1971) and Muslim insurgency",
       "Proclamation No. 1081, 21 Sep 1972, promising a 'New Society'"],
  clue:"A proclamation numbered 1081, justified by a 1971 bombing at Plaza Miranda." });
add("Early democracies", { id:"ns-indoparties", title:"Indonesia: parties and cabinets", when:"1949–1955",
  q:"Who were Indonesia's main parties and why was parliamentary government unstable?", exp:"Indonesian parties represented very different religious, ideological and regional bases, so there was no shared ground for stable coalitions. Governments depended on horse-trading and collapsed repeatedly, five cabinets in six years, which discredited parliamentary democracy. This is a clear example of power being distributed among groups held together only by anti-colonialism.",
  pts:["Masjumi (Islamic, Outer Islands); NU (traditionalist Islamic, Java); PNI (Sukarno-linked); PKI (workers); PSI (Jakarta intellectuals); Parkindo (Christian)",
       "No common ground",
       "Five cabinets rose and fell 1949–55 via horse-trading"] });
add("Early democracies", { id:"indonesia55", title:"Indonesia's 1955 election and constitutions", when:"1945–1955",
  q:"What were the results of the 1955 election and how had the constitution changed?", exp:"The 1955 election was meant to settle who governed, but the vote split almost evenly among four parties and along Java versus Outer Islands lines, so it produced no majority and deepened divisions. The frequent constitutional changes show Indonesia had little time to develop familiarity with any one system. Together these made parliamentary politics look unworkable and helped justify Sukarno’s move to Guided Democracy.",
  pts:["29 Sep 1955: PNI 22.3%, Masjumi 20.9%, NU 18.4%, PKI 16.4%; 91.5% of 39m voted",
       "No majority; sharp Java/Outer Islands split",
       "1945 Constitution (strong president) → 1949 RUSI federal parliamentary → 1950 unitary Republic",
       "Elections postponed five years to accommodate Dutch-appointed legislators"],
  clue:"A 1955 election in which four parties each won between 16% and 23% with 91.5% turnout." });
add("Early democracies", { id:"ns-pkigrowth", title:"PKI growth and regional rebellions", when:"1954–1958",
  q:"How did the PKI's growth and regional rebellions weaken parliamentary democracy?", exp:"The PKI’s rapid growth alarmed both the military and Islamic groups, polarising politics. The regional rebellions protested centralisation and tolerance of the PKI, and the army’s suppression of the PRRI raised its prestige and its role in civil administration. This illustrates how the masses’ demands and the military’s response weakened democracy and strengthened the army as a political force.",
  pts:["PKI membership tripled 1954–55 to 1 million; c.3m by early 1960s (second-largest in Asia)",
       "Alarmed the military and Islamists",
       "Sumatra/Sulawesi rebellions from Dec 1956 over centralisation and PKI tolerance",
       "1958 PRRI rebellion crushed by the army, boosting its prestige and civil role"] });
add("Early democracies", { id:"ns-guideddem", title:"Sukarno's Guided Democracy", when:"1957–1960",
  q:"How did Sukarno replace parliamentary democracy?", exp:"Sukarno framed majority-vote democracy as an alien import to justify replacing it with consensus-style rule under his guidance. Nasakom was meant to balance the military, Islamists and PKI, and restoring the 1945 Constitution gave him strong presidential powers. Dismissing parliament and cancelling elections for fear of a PKI showing shows that the real aim was to avoid electoral uncertainty, marking Indonesia’s turn to authoritarianism.",
  pts:["Decried '50 percent plus one democracy' as alien",
       "21 Feb 1957 National Advisory Council",
       "Nasakom: nationalism–religion–communism (military–Islamists–PKI)",
       "Restored 1945 Constitution (1959); dismissed parliament (1960) for an appointed Provisional People's Consultative Assembly",
       "Cancelled 1960 elections fearing a PKI showing"],
  clue:"A system Sukarno justified by attacking '50 percent plus one democracy'." });
add("Early democracies", { id:"ns-afpfl", title:"Burma: AFPFL factionalism and Buddhist Socialism", when:"1948–1958",
  q:"Why did the AFPFL fragment and how did U Nu's ideology alienate minorities?", exp:"The AFPFL was united mainly by the independence struggle, so once in power its factions pulled apart, and Aung San’s death removed the trust that tied minorities to it. U Nu’s Buddhist Socialism appealed to the Burman majority but alienated Christian minorities, while the failure of Pyidawtha undermined his record. The 1958 split shows how elite disunity eroded the democratic system from within.",
  pts:["AFPFL a broad coalition prone to factionalism; Aung San's death broke trust with minorities",
       "U Nu's 'Buddhist Socialism' (Buddhism + Marxism) antagonised Christian Karens, Chins, Kachins",
       "Pyidawtha four-year plan failed",
       "Jan 1958 split: 'Stable' (Ba Swe, Kyaw Nyein) vs U Nu's 'Clean'"] });
add("Early democracies", { id:"ns-caretaker", title:"Burma: Ne Win's caretaker government and insurgencies", when:"1948–1960",
  q:"Why did Ne Win form a caretaker government, and what insurgencies did Burma face?", exp:"U Nu’s unconstitutional handling of the budget and his invitation to Ne Win show weak elite commitment to constitutional process. The caretaker government’s success in restoring order made the army look like a capable alternative to civilian politicians, an image that later underpinned Ne Win’s legitimacy. Insurgencies that were contained but never defeated kept the military central to the survival of the state.",
  pts:["Facing a no-confidence vote (1958), U Nu passed the budget without debate, then asked Ne Win to govern",
       "Caretaker 18 months stabilised the country; power returned after Feb–Mar 1960 election",
       "Karen National Defence Organization rebelled from 1948 (seized Moulmein, Bassein, Prome; threatened Rangoon)",
       "Than Tun's White Flag communists rebelled; both contained not defeated"] });
add("Early democracies", { id:"ns-burma62", title:"Ne Win's 1962 coup", when:"1961–2 Mar 1962",
  q:"What triggered Ne Win's coup?", exp:"U Nu’s State Religion Bill and broken promises of new states deepened minority alienation, and growing insurgent control made the civilian government look unable to hold the Union together. The State Religion Bill also enraged the military itself. The coup thus followed from the factors of elite beliefs and failure to accommodate minorities, and began military rule lasting to 2010.",
  pts:["1961 State Religion Bill enraged non-Buddhist minorities and the military",
       "U Nu reneged on 1960 promises of Arakanese/Mon states",
       "By end-1961 insurgents held one-tenth of the country",
       "2 Mar 1962 largely bloodless coup; constitution suspended; Union Revolutionary Council"],
  clue:"A March 1962 coup following a bill making Buddhism the state religion." });
add("Early democracies", { id:"ns-thai1932", title:"Thailand's 1932 revolution", when:"1932–1935",
  q:"How did absolute monarchy end in Thailand, and why did democracy not take root?", exp:"The 1932 revolution replaced absolute monarchy with a constitutional one, but it was a coup by a small Western-educated elite rather than a mass movement, and there was no democratic tradition to build on. Divisions appeared at once, as Pridi’s reforms were rejected and royalists counter-attacked. A half-nominated Assembly kept power in elite hands, which helps explain why military figures like Phibun soon dominated.",
  pts:["Chakri absolute rule since 1782; no democratic tradition",
       "Western-educated 'Promoters' (Pridi, Phibun); bloodless coup 24 Jun 1932 forced Prajadhipok to accept constitutional monarchy",
       "Pridi's land redistribution rejected as leftist by his own People's Party",
       "Royalist counter-coup defeated; Prajadhipok abdicated 1935 for 10-year-old Ananda Mahidol",
       "1932 Constitution: unicameral Assembly half royally nominated, half indirectly elected"] });
add("Early democracies", { id:"ns-thaipostwar", title:"Thailand's post-war democracy and the 1947 coup", when:"1945–1951",
  q:"Why did post-war Thai democracy collapse in 1947?", exp:"The 1946 Constitution was more democratic, but personal rivalries produced nine administrations in three years, and economic dislocation fuelled strikes that the militarists exploited. The unexplained death of King Ananda was used to discredit Pridi, giving the military cover to stage a coup in the name of ‘Nation, Religion and King’. The 1951 Silent Coup then removed remaining civilian power, showing how elite rivalry let the army return.",
  pts:["1946 Constitution (Seni, Pridi): fully elected bicameral legislature; 9 administrations 1945–48 amid Pridi/Seni/Phibun rivalry",
       "1945 mass strikes; militarists funded anti-government papers with bankers and communists",
       "King Ananda found shot 6 Jun 1946 (unexplained), used against Pridi",
       "8 Nov 1947 coup (Phibun, Phin, Phao, Sarit) claiming 'Nation, Religion and King'; Pridi fled by 1949; Phibun PM April 1948",
       "1951 'Silent Coup': military cabinet 19/25"],
  clue:"A 1947 coup that followed the unexplained shooting of a young king in 1946." });

/* ── Cold War and communist states ── */
add("Cold War & communist states", { id:"ns-drv", title:"North Vietnam (DRV)", when:"1954–1975",
  q:"How was the DRV organised and governed?", exp:"Years of anti-colonial resistance gave the North’s communists deep rural legitimacy, which allowed them to carry out land redistribution and socialist planning with broad support. Although the 1960 constitution gave Ho absolute powers, he practised collective leadership, sharing key institutions among senior revolutionaries. This combination of revolutionary legitimacy and Party control explains the DRV’s stability compared with the South.",
  pts:["ICP (dissolved 1951) replaced by Lao Dong Party; PAVN from Vietminh",
       "Strong rural legitimacy enabled land redistribution and socialism",
       "1960 constitution: absolute presidential powers for Ho, though collective leadership practised",
       "Giap defence, Pham Van Dong government, Truong Chinh National Assembly",
       "First Three-Year Plan 1958–60"] });
add("Cold War & communist states", { id:"ns-rvn", title:"South Vietnam (RVN)", when:"1955–1975",
  q:"Why did the RVN lack legitimacy?", exp:"Diem had no revolutionary legitimacy, and his nepotism, corruption and persecution of religious groups, including the Buddhist majority, alienated much of the population. The NLF exploited this with pro-poor land and tax policies, gaining control of most villages. When the Buddhist Crisis made Diem a liability, the US sanctioned his removal, and the instability that followed showed that the RVN rested on US support rather than popular backing.",
  pts:["Diem despotic and corrupt; brothers Nhu, Thuc, Can, Luyen in key posts",
       "Persecuted Cao Dai/Hoa Hao and Buddhist majority (Diem Catholic)",
       "NLF formed 1960; held ~⅔ of southern villages by 1962 via pro-poor land/tax policies",
       "Buddhist Crisis 1963 → US-sanctioned coup killed Diem and Nhu (Nov 1963)",
       "Six governments 1963–65; Thieu 1965–75 with rigged elections"] });
add("Cold War & communist states", { id:"ns-2iw", title:"Second Indochina War and reunification", when:"1964–1976",
  q:"Trace the Second Indochina War to reunification and its cost.", exp:"US escalation after Tonkin Gulf brought massive force, but Tet showed that military success did not equal political victory, turning US opinion. Vietnamization and the Paris Accords allowed US withdrawal, after which the North reunified the country. The heavy costs, and Clifford’s view that it was ‘a civil war in Vietnam’, support the argument that the Domino Theory misread the conflict, since communism did not spread beyond Indochina.",
  pts:["Tonkin Gulf Resolution (Aug 1964); carpet bombing Feb 1965; Rolling Thunder; Tet (30 Jan 1968); My Lai; Agent Orange",
       "Vietnamization; Paris Accords 1973; US withdrawal completed 29 Mar 1973",
       "Saigon fell April 1975; SRV proclaimed 12 Jul 1976",
       "c.600,000 North Vietnamese and 58,000 US soldiers dead",
       "Clark Clifford: 'a civil war in Vietnam'; Domino Theory did not materialise"] });
add("Cold War & communist states", { id:"ns-sihanouk", title:"Sihanouk's Cambodia and Lon Nol's coup", when:"1955–1970",
  q:"How did Sihanouk rule, and why was he overthrown?", exp:"Sihanouk used fraud and intimidation to make his Sangkum dominant and eliminate rivals, so Cambodia’s democracy was hollow. His attempt at neutrality, allowing North Vietnamese bases while permitting US bombing, satisfied neither side and alienated both the right and the communists. This left him vulnerable to the US-backed Lon Nol coup, a clear case of Cold War pressures toppling a domestic leader.",
  pts:["Abdicated 1955; Sangkum won 83% and all seats (1955), repeated 1958, 1962 via fraud/intimidation",
       "Democratic Party disbanded 1957; Pracheachon intimidated; editors killed/detained",
       "Allowed North Vietnamese bases (1966) and secret US bombing (1969), alienating both sides",
       "Overthrown March 1970 by US-backed Lon Nol"],
  clue:"A former king whose movement won 83% and every seat in 1955, overthrown while abroad in 1970." });
add("Cold War & communist states", { id:"ns-khmerrouge", title:"Khmer Rouge and the Vietnamese invasion", when:"1970–1992",
  q:"How did the Khmer Rouge come to power and how did its rule end?", exp:"After his overthrow, Sihanouk’s alliance with the Khmer Rouge, backed by China and North Vietnam, lent it support in the civil war that destroyed Lon Nol’s regime. Khmer Rouge rule then produced genocide. Its end came through the Sino-Soviet Split: Vietnam, a Soviet client, invaded to oust a PRC client. The CGDK’s retention of the UN seat with ASEAN support shows how regional and Cold War alignments outlasted the regime itself.",
  pts:["Sihanouk allied with the Khmer Rouge (backed by China, North Vietnam)",
       "Took Phnom Penh April 1975; half the population refugees or killed/wounded",
       "Pol Pot, Khieu Samphan emptied cities; 1–2 million of 8 million died (1975–78)",
       "Dec 1978 Vietnam invaded (Sino-Soviet split), installed Heng Samrin",
       "CGDK (1982) kept the UN seat with ASEAN backing; Vietnam withdrew by 1992; Cambodian People's Party"] });
add("Cold War & communist states", { id:"ns-laoscw", title:"Laos: coalitions and communist victory", when:"1957–1997",
  q:"How did the Pathet Lao come to power?", exp:"Each attempt at coalition collapsed under external pressure, first US pressure in 1959 and then the three-way civil war, while Kennedy’s unwillingness to commit troops limited the US response. Once US involvement in Indochina ended, the Pathet Lao, backed by North Vietnam, could overthrow its rivals. Its later reliance on Soviet aid shows how Cold War support networks created and sustained communist government in Laos.",
  pts:["1957 coalition collapsed 1959 under US pressure",
       "1960 Kong Le coup: three-way war (right-wing, Pathet Lao, neutralists); Kong Le later allied with Pathet Lao",
       "1961 ceasefire (Kennedy unwilling to send troops); coalition collapsed by 1963",
       "Feb 1973 Treaty of Vientiane; Pathet Lao took power 1975: Lao PDR (Kaysone PM, Souphanouvong president)",
       "One-party, Soviet aid; ASEAN 1997"] });

/* ── Consolidation A: Indonesia, Philippines, Thailand ── */
add("Consolidation: Indonesia", { id:"ns-sukarnogd", title:"Sukarno's Guided Democracy in practice", when:"1957–1965",
  q:"How did Sukarno consolidate power and why did it fail?", exp:"Sukarno used ideas of consensus and Nasakom to justify an appointed assembly, but his power depended on balancing the military-Islamist alliance against the PKI, two forces he could not reconcile. Economic collapse and an isolating foreign policy weakened his legitimacy, while the army grew stronger by running nationalised Dutch firms and crushing rebellions. This explains why Guided Democracy was unstable and why the army could take over in 1965.",
  pts:["Nasakom; gotong royong/mushawara justified appointed assembly",
       "Balanced military–Islamists against PKI; reconciled neither",
       "Inflation 500% by 1965: 'basket case'",
       "Konfrontasi (1963) and West Irian isolated him",
       "Military became economic force by running nationalised Dutch firms; crushed rebellions by 1959"] });
add("Consolidation: Indonesia", { id:"gestapu", title:"Gestapu Coup and the 1965–66 killings", when:"30 Sep 1965 – Mar 1967",
  q:"What happened after 30 September 1965 and what was the Cold War dimension?", exp:"The murder of six generals gave the army the opportunity to destroy the PKI, removing one side of Sukarno’s balancing act and leaving him without a power base. Suharto then rose to the presidency. Western financial support and CIA propaganda for the purge show how Cold War anti-communism shaped domestic power struggles, helping to install a pro-Western military regime.",
  pts:["Pro-communist officers murdered six generals",
       "Nasution and Suharto led massacre of PKI: up to half a million killed, hundreds of thousands imprisoned",
       "Sukarno sidelined; Suharto president March 1967",
       "US/Western financial support and CIA propaganda backed the purge"],
  clue:"A night in which six generals were murdered, followed by killings of up to half a million." });
add("Consolidation: Indonesia", { id:"ns-suhartostyle", title:"Suharto's leadership style", when:"1965–1998",
  q:"Contrast Suharto's style with Sukarno's.", exp:"Where Sukarno was mercurial and populist, Suharto was calculating and ruled through personal loyalty rather than institutions. The ‘Kiss’ pattern meant elites dealt with him individually, keeping them divided and dependent on him, and his distrust of ABRI’s hierarchy led him to rely on networks reporting directly to him. This personalised control explains both the New Order’s long durability and why it collapsed with him.",
  pts:["Calculating and personalistic vs mercurial Sukarno",
       "'Sultanistic'; 'Kiss' — ke istana sendiri-sendiri, to the palace one by one",
       "Distrusted ABRI hierarchy; relied on personal loyalty networks (Kostrad reporting directly)"] });
add("Consolidation: Indonesia", { id:"ns-golkar", title:"Golkar and controlled elections", when:"1971–1997",
  q:"How did Golkar ensure electoral dominance?", exp:"Golkar gave Suharto’s regime the appearance of electoral legitimacy while ensuring the result was never in doubt. Compulsory affiliation for civil servants, forcing opposition parties into two weak groupings and requiring all groups to adopt Pancasila removed real competition. This illustrates the Cluster A pattern of manipulated elections providing a thin veneer of legitimacy, comparable to Marcos’s KBL.",
  pts:["Formed by the army to counter PKI unions",
       "Won every election from 1971: 65% → 74.5% (1997)",
       "Compulsory affiliation for civil servants",
       "Opposition merged into PPP (Islamic) and PDI (others), 1972–73",
       "1985 Ormas law: all groups must adopt Pancasila"],
  clue:"A party formed by the army that won 65% in 1971 and 74.5% in 1997." });
add("Consolidation: Indonesia", { id:"ns-dwifungsi", title:"Dwifungsi and economic patronage", when:"1958–1983",
  q:"What was dwifungsi and how did economic patronage support the New Order?", exp:"Dwifungsi gave the military a legal right to a political and social role, so soldiers filled the cabinet and governorships, binding the army to the regime. Oil wealth and the expanding state let Suharto reward Chinese cukong businessmen and win over the middle class through economic growth. Patronage was a key source of power, but the same cronyism later became corrosive when the economy failed.",
  pts:["'Dual function' from Nasution's 1958 speech, in law 1982",
       "Late 1970s: half the cabinet and ⅔ of governorships military",
       "Oil revenues quadrupled after 1973–74; state share of GDP 13% → 41% by 1983",
       "Bound cukong businessmen (Liem Sioe Liong) and middle class"] });
add("Consolidation: Indonesia", { id:"ns-neworderopp", title:"Opposition under the New Order", when:"1965–1994",
  q:"How did Suharto deal with challenges and opposition?", exp:"Suharto removed rivals first, destroying the PKI and sidelining Nasution and the kingmakers, then dealt with unrest through violent crackdowns and laws that restricted mass participation. Elite criticism like the Petition of Fifty made no impact, showing how closed the system was. However, the openness period revealed opposition growing among students, workers and the PDI under Megawati, foreshadowing the forces behind his fall.",
  pts:["PKI destroyed; Nasution and four 'kingmakers' sidelined",
       "Malari riots 1974 (11 dead); Tanjung Priok 1984 (28+)",
       "SK 028 (1974), NKK/BKK campus controls (1977), Ormas (1985)",
       "1980 Petition of Fifty had no impact",
       "Keterbukaan 1987–94: students, SBSI Medan strikes (1994), PDI under Megawati"] });
add("Consolidation: Indonesia", { id:"ns-suhartofall", title:"Fall of Suharto", when:"1997–21 May 1998",
  q:"Why did Suharto fall in 1998?", exp:"The Asian Financial Crisis removed the economic growth that had justified the New Order and exposed the cronyism behind it. IMF-required subsidy cuts triggered protests, and the Trisakti killings escalated them into riots. The decisive factor was military defection: once key generals withdrew support, Suharto could not survive. This shows the notes’ point that he failed to reform in time, unlike regimes that adapted.",
  pts:["AFC exposed cronyism ('Madam Tien Percent'; crony banks)",
       "IMF-forced subsidy cuts sparked protests",
       "Four Trisakti students killed 12 May 1998 → riots (~2,250 dead, anti-Chinese violence)",
       "Military defections (Yudhoyono, Wiranto over Prabowo)",
       "Resigned 21 May 1998 to Habibie"],
  clue:"A resignation on 21 May 1998 after four Trisakti students were shot." });
add("Consolidation: Indonesia", { id:"ns-suhartocw", title:"New Order and the Cold War", when:"1966–1993",
  q:"How did Cold War alignment help Suharto?", exp:"By turning against communism, ending Konfrontasi and co-founding ASEAN, Suharto made Indonesia a valued Western partner. In return the West supplied aid and trade and tolerated his human rights abuses, strengthening the regime. When Cold War urgency faded and the Clinton administration became more critical, this external support weakened, illustrating how US backing first propped up and later undermined strongmen.",
  pts:["Reversed Sukarno's pro-PRC leaning",
       "Ended Konfrontasi; co-founded ASEAN 1967",
       "Western aid and tolerance of abuses",
       "Until Clinton's more critical 1990s stance (1993 arms sale veto)"] });
add("Consolidation: Indonesia", { id:"ns-indodem", title:"Indonesia's democratic transition", when:"1998–2001",
  q:"Why was Indonesia's democratic transition unstable?", exp:"Habibie and Wahid opened politics to new parties and Golkar lost the 1999 election, a clear break with the New Order. But decades of centralised control meant no group could quickly stabilise the new system, so corruption, communal violence and separatism persisted, and Wahid himself was dismissed. This shows that the return to democracy within Cluster A was imperfect and unstable.",
  pts:["Habibie (1998–99), Wahid (1999–2001) opened politics: PDIP, PAN (Amien Rais), PKB",
       "April 1999: PDIP 33.7% vs Golkar 22.4%",
       "No group able to stabilise quickly; corruption, communal violence, Aceh and Papua",
       "Wahid dismissed 2001; Megawati succeeded"] });
add("Consolidation: Philippines", { id:"ns-marcosstyle", title:"Marcos's style and the 1973 Constitution", when:"1972–1981",
  q:"How did Marcos use martial law to entrench himself?", exp:"Marcos used his skill in patron-client politics and the cover of martial law to rewrite the rules. The 1973 Constitution’s parliamentary system let him combine presidential and prime-ministerial power and escape term limits, while referendums replaced competitive elections. This shows a leader using constitutional forms to entrench personal rule, typical of the highly personalistic leadership in Cluster A.",
  pts:["Skilled manipulator of patron-client politics; convicted then acquitted of a 1939 murder",
       "1973 Constitution: parliamentary system letting him hold presidential and prime-ministerial power",
       "Circumvented term limits; ruled initially by referendum"] });
add("Consolidation: Philippines", { id:"ns-marcospower", title:"Marcos's sources of power", when:"1972–1986",
  q:"What were the sources of Marcos's power?", exp:"Marcos built a ruling movement modelled on Golkar, greatly expanded and empowered the military so it depended on him, and rewarded loyal cronies with monopolies. These three sources tied key groups to his survival. However, politicising the army and concentrating wealth among cronies created resentment and military factionalism that later contributed to his fall.",
  pts:["Kilusang Bagong Lipunan (1978), paralleling Golkar",
       "AFP 45,000 → 150,000 (1967–86); 45.7% of spending by final year; judicial, economic, media roles",
       "Cronies with monopolies: Cojuangco (coconuts/San Miguel), Benedicto (sugar), Disini (cigarettes)"] });
add("Consolidation: Philippines", { id:"ns-marcosopp", title:"Opposition to Marcos", when:"1972–1986",
  q:"How did opposition to Marcos grow?", exp:"Mass arrests and the exile of Ninoy Aquino suppressed opposition, but his assassination turned grief into a movement around Corazon Aquino and the Church. Martial law also failed to contain the communist and Muslim insurgencies, which grew sharply, undermining Marcos’s claim to provide order. The factionalisation of the military under RAM and Enrile’s distancing meant his key pillar of support was weakening.",
  pts:["General Order No. 2: ~70,000 political prisoners by 1977",
       "Ninoy Aquino imprisoned 1972–80, exiled; assassinated 1983 (blamed on Imelda/Gen. Ver)",
       "Opposition rallied around Corazon Aquino and Cardinal Sin",
       "Military factionalised (RAM); Enrile distanced himself",
       "NPA regulars 1,900 → 24,430 (1973–86); MNLF grew"] });
add("Consolidation: Philippines", { id:"marcos", title:"1986 snap election and EDSA", when:"Feb 1986",
  q:"How did Marcos fall?", exp:"The fraudulent snap election destroyed Marcos’s remaining claim to legitimacy. The mutiny by Enrile and Ramos, combined with Cardinal Sin’s call that brought a million civilians onto EDSA, meant that the military and the masses turned against him at once. When troops and US support withdrew, he had no base left. This shows how Cluster A regimes could be toppled by mass uprising once legitimacy collapsed.",
  pts:["Marcos claimed a 1.6m win; poll-watchers showed Aquino winning by ~800,000",
       "Enrile and Fidel Ramos mutinied 22 Feb 1986",
       "Cardinal Sin's radio call brought 1m+ onto EDSA",
       "Troops and US support withdrew; Marcos fled to Hawaii 26 Feb: bloodless People Power"],
  clue:"A February 1986 revolution on a Manila highway after a disputed snap election." });
add("Consolidation: Philippines", { id:"ns-philcw", title:"Philippines and the Cold War", when:"1947–1991",
  q:"How did US Cold War ties affect Marcos?", exp:"US bases and the defence treaty made the Philippines strategically vital, so Washington backed Marcos as long as he served anti-communist goals. As Cold War urgency declined and he failed to defeat the NPA, he became a liability and US support eroded, which helped seal his fall in 1986. The non-renewal of the bases after 1991 shows how the relationship changed once the Cold War ended.",
  pts:["1947 Military Bases Agreement (Clark, Subic); 1951 Mutual Defence Treaty",
       "US support tied to Marcos's anti-communism",
       "Eroded mid-1980s: declining urgency, failure to beat the NPA",
       "Bases not renewed after 1991 (Senate rejection; Mt Pinatubo)"] });
add("Consolidation: Philippines", { id:"ns-phildem", title:"Philippine democracy 1986–2000", when:"1986–2001",
  q:"How stable was Philippine democracy after 1986?", exp:"Democracy was restored but remained fragile: Aquino had to compromise with old elites and survive coup attempts, and Ramos revived crony privileges and pork-barrel politics. Yet Ramos accepted the Supreme Court’s block on re-election, showing some institutional constraint. Estrada’s removal through EDSA II and military withdrawal shows that crises were still resolved through the streets and the army rather than fully through institutions.",
  pts:["Aquino: 1987 Constitution (single six-year term); compromised with elites; survived coup attempts (RAM, 1986–89)",
       "Ramos (1992–98): restored crony privileges, pork-barrel; accepted Supreme Court block on re-election",
       "Estrada impeached; trial collapsed; EDSA II and military withdrawal forced resignation Jan 2001",
       "Gloria Macapagal-Arroyo succeeded"] });
add("Consolidation: Thailand", { id:"ns-thaimil", title:"Thai military rule: leaders and US aid", when:"1947–1973",
  q:"Who led Thailand's military regime and how did US aid help?", exp:"Thailand’s military rulers, especially Sarit, built legitimacy on King, Religion and Nation through paternalistic rule. US aid, which grew dramatically as Thailand became a Cold War ally, funded and strengthened the armed forces. Baker and Phongpaichit’s judgement that it ‘consolidated Thailand’s militarised state’ supports the argument that Cold War aid propped up authoritarian rule in Cluster A.",
  pts:["Phibun (1947–58), Sarit (1958–63), Thanom (1963–73)",
       "Sarit: 'benevolent paternalism' built on King–Religion–Nation",
       "US military aid quadrupled in 1960s; budget ~US$20m → ~US$250m/yr",
       "Baker & Phongpaichit: 'consolidated Thailand's militarised state'"],
  clue:"A military regime whose budget grew from about US$20m to US$250m a year on American aid." });
add("Consolidation: Thailand", { id:"ns-thaisources", title:"Thai military rule: sources of power and challenges", when:"1949–1971",
  q:"How did the Thai military use constitutions and the monarchy, and what challenged it?", exp:"Constitutions were repeatedly rewritten or abolished to suit whichever faction held power, so they served as tools rather than constraints. Sarit tied the army to the revived monarchy, boosting both. Yet economic growth produced a business class and students who began to oppose military rule, and frequent coups and the CPT insurgency showed instability within the regime, setting up the challenge of 1973.",
  pts:["Constitutions suspended/rewritten: 1949 abolished 1951; 1968 (military-drafted) abolished 1971",
       "Sarit revived royal ceremony, linking monarchy with army",
       "Growth 8.2%/yr (1961–70) created business class and students",
       "Phibun survived 3 coups (1948–51), deposed by Sarit 1957; CPT insurgency from 1967",
       "Businessmen won 46% of seats in 1969"] });
add("Consolidation: Thailand", { id:"ns-thai73", title:"October 1973 uprising", when:"Oct 1973",
  q:"How did military rule end in 1973?", exp:"Student protests over arrested activists grew into a mass movement, and the regime’s lethal response destroyed its legitimacy. The decisive act was King Bhumibol ordering Thanom and Praphas to resign, showing the monarchy as the key moderating force in Thai politics. This ended a quarter-century of military dominance and is an example of a Cluster A mass uprising toppling a regime.",
  pts:["National Students' Centre protests over arrested leafleteers",
       "500,000+ demonstrators; hundreds killed",
       "King Bhumibol ordered Thanom and Praphas to resign; they fled",
       "Ended a quarter-century of military dominance"],
  clue:"A 1973 uprising of half a million ended when the King ordered two military leaders to leave." });
add("Consolidation: Thailand", { id:"ns-thai76", title:"Democratic interlude and Thammasat", when:"1973–6 Oct 1976",
  q:"Why did Thailand's 1973–76 democracy collapse?", exp:"The 1973–76 democracy rested on weak, fractious coalitions, with 22 parties and no majority, so government lacked authority. Massive strikes and demonstrations deepened polarisation, and Thanom’s return provoked right-wing militias into the Thammasat massacre, giving the military a pretext for a fresh coup. This shows how elite disunity and unaccommodated mass demands brought back military rule.",
  pts:["Seni and Kukrit Pramoj's fractious coalitions; 1974 Constitution",
       "1975 election: 22 parties, no majority",
       "1,333 strikes and 322 demonstrations 1973–75",
       "Thanom's return (Oct 1976) → Thammasat massacre 6 Oct 1976 (46+ officially dead)",
       "Coup by Admiral Sangad Chaloryu"] });
add("Consolidation: Thailand", { id:"ns-prem", title:"Prem's managed democracy", when:"1980–1988",
  q:"What characterised Prem's 'managed democracy'?", exp:"Prem’s system worked by balancing the military, bureaucracy and business rather than letting one dominate, with an elected House checked by an appointed Senate. That compromise produced Thailand’s longest stretch of stable parliamentary government. Over time, business representation grew and challenges to military budget secrecy succeeded, gradually weakening the military’s hold through institutional means.",
  pts:["Balanced military, bureaucracy, business under 1978 Constitution (elected House, appointed Senate)",
       "Longest period of undisputed parliamentary function",
       "Business share of Assembly 1/3 (1979) → 2/3 (1988)",
       "Challenges to military budget secrecy weakened the military"] });
add("Consolidation: Thailand", { id:"ns-blackmay", title:"1991 coup and Black May 1992", when:"Feb 1991 – May 1992",
  q:"What caused the 1991 coup and Black May?", exp:"The military resented Chatichai’s corrupt, business-friendly rule and staged the 1991 coup, but its promise of elections meant Suchinda’s appointment as unelected PM looked like a betrayal. Mass protests met with lethal force, and once again King Bhumibol intervened to force the leader out. This repeats the 1973 pattern and highlights the King as the decisive moderating force.",
  pts:["Chatichai's corrupt, business-friendly government angered the military",
       "NPKC (Gen. Suchinda) seized power Feb 1991, promised elections",
       "Unelected Suchinda made PM 1992; protests led by Chamlong; 500,000+, hundreds killed",
       "King intervened; Suchinda resigned; 1992 election (Chuan Leekpai)"],
  clue:"May 1992 protests against an unelected general-turned-premier, ended by royal intervention." });
add("Consolidation: Thailand", { id:"ns-thai92", title:"Thailand after 1992 and evaluation", when:"1992–2000",
  q:"How did Thai democracy develop after 1992, and what does the Thai case show about constitutions?", exp:"After 1992, reforms strengthened rights and judicial checks and the military’s budget share fell, showing real democratisation, though unstable cabinets and the Asian Financial Crisis still disrupted politics. The notes’ evaluation is that Thai constitutions were tools of whoever held power, since the most stable period under Sarit had none, and that the King, not any government, was the decisive moderating force in 1973, 1976 and 1992.",
  pts:["1997 'People's Constitution' strengthened rights and judicial checks",
       "Military budget share 22% (1985) → 13% (1996); 3 cabinet changes in the 1990s",
       "AFC discredited the Democrats → Thaksin's party (1998)",
       "Constitutions were tools of whoever held power; most stable period (Sarit) had none",
       "The King was the decisive moderating force in 1973, 1976, 1992"] });

/* ── Consolidation B: Burma & Vietnam ── */
add("Consolidation: Burma & Vietnam", { id:"ns-clusterb", title:"Why Burma and Vietnam stayed authoritarian", when:"1962–2000",
  q:"Explain why Indonesia, the Philippines and Thailand reverted to democracy while Burma and Vietnam did not.", exp:"Burma and Vietnam stayed authoritarian because they never relied on democratic appearances, so there were no competitive elections or opposition space that crises could exploit. Being much less dependent on US aid, they faced no outside pressure to keep up democratic pretences, unlike Cluster A regimes. Vietnam’s Doi Moi shows that economic opening without political liberalisation could preserve control, as in China and unlike the USSR.", qs:"notes",
  pts:["Burma (Tatmadaw 1962–2010) and VCP (since 1976) endured",
       "Lacked democratic appearances (competitive elections, opposition space)",
       "Far less dependent on US aid, so no pressure for democratic pretence",
       "Doi Moi let Vietnam open economically without losing control, like China and unlike the USSR"] });
add("Consolidation: Burma & Vietnam", { id:"ns-newin", title:"Ne Win's legitimacy and style", when:"1962–1988",
  q:"What was the basis of Ne Win's legitimacy and his style?", exp:"Ne Win’s legitimacy came from his long role in the nationalist struggle as one of the Thirty Comrades and from the order his caretaker government had restored. His ‘gradual and cautious’ style (Taylor), including releasing prisoners and the 1980 amnesty that let U Nu return, avoided needless confrontation. This helps explain the durability of military rule beyond coercion alone.",
  pts:["One of the Thirty Comrades; long involvement since before WWII",
       "Stability of 1958–60 caretaker government",
       "'Gradual and cautious' (Taylor): released prisoners after 2 years",
       "1980 amnesty allowed U Nu to return"] });
add("Consolidation: Burma & Vietnam", { id:"ns-bspp", title:"BSPP and the Burmese Way to Socialism", when:"1962–1974",
  q:"How did the BSPP and its ideology entrench single-party rule?", exp:"The BSPP gave military rule an institutional form, becoming the only legal party, and the 1974 Constitution replaced the federal structure with a unitary single-party state, ending minorities’ constitutional autonomy. The Burmese Way to Socialism supplied an ideology fusing Marxism and Buddhism to justify state control of the economy. Single-candidate elections show legitimacy came from ideology and the party, not competition.",
  pts:["BSPP formed July 1962; sole legal party from 1964",
       "1974 Constitution: single-party, unitary state replacing federal structure",
       "Burmese Way to Socialism fused Marxism-Leninism and Buddhism; nationalised economy, expelled Indian/Chinese traders",
       "Elections from 1974: accept or reject the single BSPP nominee"] });
add("Consolidation: Burma & Vietnam", { id:"burmamilitary", title:"Challenges to Ne Win", when:"1962–1987",
  q:"What challenges did Ne Win's regime face?", exp:"Ne Win’s regime faced continuous ethnic and communist insurgencies, recurring student protests, and the failure of the Burmese Way to Socialism, shown by the collapse of foreign trade. The demonetisations were the most damaging because they wiped out ordinary people’s savings, turning economic failure into mass anger. This builds the causal chain leading to the 8888 Uprising.",
  pts:["Insurgents (KNLA, BCP): ~500,000 dead over four decades",
       "1962 student union building destroyed (16–100 dead); 1974–75 protests over U Thant's funeral",
       "Foreign trade 40% → 13% of GDP by 1977; partial liberalisation from 1971",
       "1985 and 1987 demonetisations wiped out savings"] });
add("Consolidation: Burma & Vietnam", { id:"ns-8888", title:"The 8888 Uprising", when:"Mar–Sep 1988",
  q:"How did the 8888 Uprising unfold?", exp:"A minor brawl escalated nationwide because it tapped into deep anger over economic collapse and the demonetisations. The violent crackdown and Ne Win’s resignation showed the regime’s loss of legitimacy, but the army did not split; instead Saw Maung’s coup created SLORC and restored control. The notes argue this revealed a legitimacy crisis that coercion could cover only for a time, while the NLD became the new focus of opposition.",
  pts:["March 1988 student–tea shop brawl escalated nationwide",
       "Sein Lwin's crackdown killed up to 3,000",
       "Ne Win resigned 23 Jul 1988",
       "Saw Maung's coup 18 Sep 1988 created SLORC",
       "NLD formed 28 Sep 1988 (Aung San Suu Kyi, Aung Gyi)"],
  clue:"A 1988 uprising that began with a tea shop brawl and ended in a coup creating SLORC." });
add("Consolidation: Burma & Vietnam", { id:"ns-slorc", title:"SLORC and the 1990 election", when:"1988–1995",
  q:"How did SLORC respond to Aung San Suu Kyi and the 1990 election?", exp:"Aung San Suu Kyi gave the opposition a powerful symbol, and her outreach to minorities alarmed the military, which responded by securing ceasefires with most armed groups. The NLD’s landslide in 1990 showed how little popular support the military had, yet SLORC simply refused to hand over power and ruled by martial law. This illustrates that the regime relied on coercion rather than electoral legitimacy.",
  pts:["Aung San Suu Kyi returned from Oxford 1988; minority outreach alarmed the military",
       "Ceasefires with 17 of 21 armed groups early 1990s",
       "May 1990: NLD 392/485 (70% turnout); NUP 10; SLORC refused to hand over",
       "Martial law; house arrest 1989–95 and 2000–02"],
  clue:"An election won 392 seats to 10 that the ruling junta refused to honour." });
add("Consolidation: Burma & Vietnam", { id:"ns-spdc", title:"SPDC, USDA and international pressure", when:"1991–2021",
  q:"How did the junta survive international pressure after 1990?", exp:"International pressure forced only limited concessions, while ASEAN membership in 1997 softened the impact of Western sanctions. The junta strengthened itself internally by purging over-mighty commanders and building the USDA as a mass organisation reaching almost every village. Its isolation during the Cold War had spared it scrutiny, and the managed roadmap to the 2008 constitution let the military keep control under nominal civilian rule.",
  pts:["US aid suspension, UN/Amnesty reports, Suu Kyi's 1991 Nobel Prize",
       "Martial law lifted 1992; some releases; ASEAN 1997 eased sanctions",
       "SPDC (1997) after purging regional commanders",
       "USDA (1993) in nearly all villages by 1996; 11m members by 1999",
       "2003 roadmap → 2008 constitution → 2010 elections; coup 2021; Cold War isolation spared scrutiny"] });
add("Consolidation: Burma & Vietnam", { id:"ns-srv", title:"The SRV 1976–86", when:"1976–1986",
  q:"How did the VCP govern after reunification?", exp:"After reunification the VCP ran the state through collective leadership by an old revolutionary troika committed to orthodox Marxism-Leninism. The Party dominated the Assembly and cabinet, and the military remained strictly under Party control, unlike in Indonesia or Thailand. This institutional rather than personal leadership is why Vietnam fits the stable authoritarian cluster.",
  pts:["1980 constitution: collective leadership, democratic centralism",
       "Troika: Pham Van Dong, Truong Chinh, Le Duan; orthodox Marxism-Leninism",
       "VCP held 92% of 395 Assembly seats; 30/34 cabinet on Central Committee",
       "Military strictly subordinate: 'the party must always control the gun'"] });
add("Consolidation: Burma & Vietnam", { id:"doimoipol", title:"Reintegrating the South and isolation", when:"1976–1986",
  q:"What problems did reintegrating the south and the Cambodian invasion create?", exp:"Reintegrating the South through re-education camps, religious persecution and forced collectivisation provoked strong resistance, which caused rice production to fall and drove a refugee exodus. The invasion of Cambodia, rooted in the Sino-Soviet Split, added international isolation and total reliance on Soviet aid. These failures created the pressures that pushed the VCP towards Doi Moi.",
  pts:["Southern officials/merchants sent to re-education camps; Catholic and Buddhist figures persecuted",
       "Only 0.6% of Mekong Delta households in cooperatives by 1982",
       "Rice 11.83m t (1976) → 9.79m t (1979); boat people exodus",
       "Cambodia invasion (1978): isolation, US embargo till 1995, total dependence on USSR/COMECON"] });
add("Consolidation: Burma & Vietnam", { id:"ns-doimoi", title:"Doi Moi and political control", when:"1986–2000",
  q:"How did Doi Moi reform the economy while keeping VCP control?", exp:"Le Duan’s death let Nguyen Van Linh launch Doi Moi, liberalising agriculture, investment and state enterprises while keeping the VCP supreme, as in Deng’s China. The 1992 Constitution allowed limited change without threatening Party control. Withdrawing from Cambodia ended Vietnam’s isolation, bringing ASEAN membership and US normalisation. The notes cite this capacity to adapt, unlike the USSR, as the reason the VCP has stayed in power.",
  pts:["Le Duan died 1986; Nguyen Van Linh launched Doi Moi, like Deng's China",
       "Resolution 10 (1988); 1987 investment law and export zones; SOEs 12,000 → 6,000 (1986–94)",
       "1992 Constitution: wider Assembly powers; 8% non-party seats",
       "Conservative 'Gorbachev-phobia'; 1996 Eighth Congress; AFC hit (70% of FDI from ASEAN)",
       "Cambodia withdrawal 1989–91 → ASEAN and US normalisation 1995"] });

/* ── Consolidation C: Malaysia & Singapore ── */
add("Consolidation: Malaysia & Singapore", { id:"ns-semidem", title:"Semi-democracies", when:"1965–2000",
  q:"Explain what makes Singapore and Malaysia 'semi-democracies' rather than either full democracies or authoritarian states.", exp:"Case’s term captures the middle ground: Singapore and Malaysia hold regular, procedurally fair elections, which gives them real legitimacy, unlike authoritarian states, but they limit liberal participation, so they are not full democracies. Coercive laws are aimed at explicit challengers, while opposition that plays by the rules is tolerated or co-opted. With the military kept apolitical, it cannot act as a rival power source.", qs:"notes",
  pts:["William Case's classification",
       "Regular, procedurally fair elections rather than heavy-handed methods, but liberal participation tightly limited",
       "'[Borrowing] cunningly some features of democracy in order substantively to avoid it' (Case)",
       "Coercive laws (Sedition Act, ISA) against challengers; co-opt opposition within rules",
       "Military strictly professional and apolitical"] });
add("Consolidation: Malaysia & Singapore", { id:"ns-msia5769", title:"Limits of ethnic politics in Malaysia", when:"1957–1969",
  q:"What were the limits of the Alliance's ethnic bargain before 1969?", exp:"The Social Contract traded Malay political primacy for Chinese economic power and citizenship, and the Tunku’s style held the bargain together. But it satisfied neither extreme: Malay ultras resented Chinese wealth, the DAP drew Chinese voters from the MCA, and the MIC could not unite Indians. Merger tensions and the National Language Act inflamed communal feeling, showing why the formula broke down in 1969.",
  pts:["Social Contract: Malay primacy (Section 153) for Chinese economic power and citizenship",
       "Tunku's informal, delegating style held the Alliance together",
       "Malay 'ultras' opposed Chinese economic dominance; DAP challenged MCA; MIC failed to unite Indians",
       "Merger tensions (1964 Singapore riots); 1967 National Language Act"] });
add("Consolidation: Malaysia & Singapore", { id:"may13", title:"13 May 1969", when:"1969–1971",
  q:"What caused the 13 May riots and what followed?", exp:"The MCA’s poor showing weakened the Alliance’s ethnic bargain, and rival rallies in Kuala Lumpur escalated into deadly riots. The suspension of Parliament and rule by the NOC under Tun Razak marked a decisive break, and the Tunku’s resignation brought Razak to power. The riots led directly to the post-1971 restructuring of Malaysian politics around Malay economic uplift and limits on sensitive debate.",
  pts:["MCA did badly against Gerakan/DAP in 1969; rival rallies in KL turned violent",
       "Official toll 196; unofficial 600–800",
       "Parliament suspended; NOC/MAGERAN under Tun Razak 1969–71",
       "Tunku resigned as PM (1970) and UMNO President (1971)"],
  clue:"A May 1969 crisis with an official toll of 196, after which Parliament was suspended." });
add("Consolidation: Malaysia & Singapore", { id:"ns-msiasources", title:"Malaysia's sources of power 1971–2000", when:"1971–2000",
  q:"How did the Malaysian government consolidate power after 1971?", exp:"After 1969 the government removed the most explosive issues from debate by banning discussion of Malay special position, language, citizenship and the sultans. The NEP built legitimacy through Malay economic uplift but also bred cronyism. Elections stayed regular but were tilted, and the Barisan Nasional co-opted almost all opposition, so the regime was stabilised by narrowing and absorbing competition rather than abolishing it.",
  pts:["Razak (NEP architect) → Hussein Onn → Mahathir (1981–2003, 'Asian values')",
       "1971 Constitution (Amendment) Act banned discussion of Malay special position, language, citizenship, sultans",
       "NEP: bumiputera equity 1.5% → 20.3%, but cronyism (Daim; Sports Toto, Berjaya)",
       "Rukunegara (1970) paralleled Pancasila; elections tilted by gerrymandering, short campaigns, rally bans",
       "Barisan Nasional (1 Jun 1974) co-opted all but DAP; Anwar (ABIM) co-opted 1982"] });
add("Consolidation: Malaysia & Singapore", { id:"ns-msiachall", title:"Lalang, Reformasi and evaluation", when:"1987–1999",
  q:"How did Mahathir deal with the 1987 UMNO split and the 1998 Anwar crisis?", exp:"Mahathir met internal challenges with institutional and coercive tools: forming UMNO Baru, sacking senior judges and detaining critics under the ISA in Operation Lalang. The Anwar crisis sparked Reformasi, yet BN kept its majority. The notes’ evaluation is that elections narrowed debate but still gave legitimate channels for opposition, so crises were contained within the system, unlike Indonesia and the Philippines where only regime replacement could resolve them.",
  pts:["1987–88 split (Musa Hitam, Razaleigh); courts ruled UMNO illegal → 'UMNO Baru'",
       "Sacked Lord President and two judges; Operation Lalang detained 100+ under ISA (1987)",
       "1998: Anwar sacked and jailed; Reformasi; Barisan Alternatif; BN kept ⅔ in 1999 via Chinese/Indian votes",
       "No strong post-independence communist insurgency (Emergency) gave anti-communist baseline",
       "Elections narrowed debate but gave legitimate channels (PAS, DAP, KeADILan), unlike Indonesia/Philippines"] });
add("Consolidation: Malaysia & Singapore", { id:"ns-sgsurvival", title:"Singapore: politics of survival", when:"1965–1993",
  q:"How did the PAP consolidate power after 1965?", exp:"Separation and the British withdrawal created a sense of vulnerability that the PAP used to rally the nation around economic survival and to depoliticise the public, under leaders who were pragmatic and firm. Security laws were used against explicit challengers, while constitutional schemes such as NCMP, GRC and NMP allowed controlled diversity without threatening PAP dominance. The notes treat these adjustments as part of the regime’s capacity to adapt.",
  pts:["LKY (1959–90) pragmatic, paternalistic; Goh (1990–2004) consultative with 'OB markers'",
       "Separation (1965) and British withdrawal (1968) created vulnerability, depoliticised the public",
       "PAP held all seats 1968, 1972, 1976, 1980",
       "Sedition Act, Religious Harmony Act (1990), ISA (Coldstore 1963; Spectrum 1987, 22 detained)",
       "NCMP (1984), GRC (1988, minority candidate), NMP (1990), elected presidency (1991/93)"] });
add("Consolidation: Malaysia & Singapore", { id:"ns-sgsocial", title:"Singapore's social controls", when:"1960–1978",
  q:"What grassroots and social controls linked citizens to the PAP?", exp:"Grassroots bodies and mass organisations created direct links between citizens and the PAP, so the state reached into everyday community life. Bringing labour under the NTUC and National Wages Council removed unions as a base for opposition, which had been the pro-communists’ strength earlier. Media regulation and state ownership limited critical voices, showing extensive but non-violent social control.",
  pts:["Community Centres, Citizens' Consultative Committees, Residents' Committees (1978)",
       "People's Association (1960)",
       "NTUC (1961) and National Wages Council (1972) depoliticised labour",
       "Newspapers and Printing Presses Act (1974); SPH, MediaCorp"] });
add("Consolidation: Malaysia & Singapore", { id:"ns-sgopp", title:"Singapore: opposition and evaluation", when:"1981–1999",
  q:"How was opposition in Singapore handled, and why was the PAP stable?", exp:"The PAP tolerated a small opposition, from Jeyaretnam’s 1981 win to a peak of four seats, but used defamation suits and the ISA against vocal critics, keeping opposition within tightly drawn limits. Its stability also rested on careful management of racial sensitivities, which prevented a repeat of 1964 and 1969 violence, and an apolitical SAF that removed the military as a rival. Alignment with the West and ASEAN added external security.",
  pts:["J.B. Jeyaretnam won Anson 1981 (Workers' Party)",
       "Opposition 2–4 seats; peak 4 in 1991 (SDP 3, WP 1)",
       "Defamation suits (Tang Liang Hong 1997); ISA (Francis Seow); Goh's 1999 limits on consultation",
       "1967 Defence White Paper → SAF; founding ASEAN; hardline on Vietnam",
       "Presidential Council for Minority Rights (1970), HDB quotas, apolitical SAF"] });

/* ── Synthesis ── */
add("Synthesis", { id:"ns-compare", title:"Comparing the three consolidation clusters", when:"synthesis",
  q:"Compare leaders, legitimacy, opposition and Cold War influence across the three clusters.", exp:"The comparison shows that how power was held explains the outcome. Personalistic rule with manipulated elections in Cluster A meant crises could topple regimes once legitimacy and US support went. Institutional rule with deep ideological control in Burma and Vietnam suppressed opposition and endured. In Singapore and Malaysia, constrained but genuine elections channelled opposition into the system and gave stable alignment, producing lasting semi-democracy.",
  pts:["Leaders: personalistic (Sukarno, Marcos, Sarit) vs institutional (VCP, Tatmadaw) vs constitutionally constrained (SG/MY)",
       "Legitimacy: manipulated elections + patronage vs single-party ideology vs genuine but constrained elections",
       "Opposition: periodic uprisings topple regimes vs suppressed vs channelled into elections",
       "Cold War: US aid propped strongmen then withdrew vs isolation/Soviet patronage vs stable alignment",
       "Outcome by 2000: reverted to democracy vs stable authoritarian vs stable semi-democracy"] });
add("Synthesis", { id:"ns-conclusion", title:"Concluding evaluation", when:"synthesis",
  q:"What are the notes' five concluding evaluation points on forming nation-states?", exp:"These points supply ready-made evaluative arguments. Decolonisation set the starting conditions but did not decide outcomes, since peaceful transfers produced both authoritarian and semi-democratic states. Elites’ capacity to compromise mattered more than the form of government, and the Cold War amplified rather than caused outcomes. Survival depended on adaptability, as Doi Moi and Singapore and Malaysia’s reforms show against Suharto and Marcos, and legitimacy is distinct from coercive power.",
  pts:["Decolonisation set initial conditions but not long-term stability (Philippines, Burma peaceful yet authoritarian)",
       "Critical variable: elites' ability to compromise and accommodate masses",
       "Cold War an amplifier, not root cause",
       "Success correlates with capacity to adapt (Doi Moi, NCMP/GRC, NEP) vs Suharto/Marcos failing to reform",
       "Legitimacy ≠ coercion: Burma 1988 vs VCP's historical legitimacy"] });
add("Synthesis", { id:"ns-military", title:"Role of the military across SEA", when:"synthesis",
  q:"Compare and contrast the role of the military across all eight case studies.", exp:"Where the military won legitimacy through independence struggles, as in Burma and Indonesia, or through repeated coups in Thailand, it became an independent political force. In Vietnam the army was born inside the Party, so it stayed subordinate. Where colonial tutelage kept forces under civilian or British control, as in Malaysia and Singapore, the military stayed professional, and the Philippines shows how a professional army could be politicised under Marcos.", qs:"notes",
  pts:["Independent political force: Burma (BIA/BNA, Tatmadaw), Indonesia (PETA, dwifungsi), Thailand (coups)",
       "Philippines: professional AFP until Marcos politicised it (RAM factionalism)",
       "Subordinate to party: Vietnam ('party commands the gun')",
       "Strictly professional, apolitical: Malaysia, Singapore (SAF built after 1965)"] });
})();
